const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (crear_lote_pendiente) -- Python es la unica autoridad.
// Este nodo NUNCA decide nada de negocio: solo empaqueta lo que ya vino
// del request HTTP (body/query), mas rutas DEV FIJAS del lado servidor
// (el navegador nunca elige un path de archivo -- ver Sticky Note de
// seguridad de este workflow). FASE 10D: base_dir_dev apunta al workdir
// REAL (Drive solo lectura), no al fixture de FASE 9.
const payload = { fecha_inicio: t.body.fecha_inicio, fecha_fin: t.body.fecha_fin, usuario_auditor: t.body.usuario_auditor || null, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_crear_lote_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_crear_lote_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());
const rp = $('RESOLVER procesar_entrada (MACROS y cierres)').first().json;

// Payload para v3.dev_api (procesar_lote) -- Python es la unica autoridad.
// FASE 11A.3: requiere_ingesta_drive=true (modo oficial de este despliegue) -- si EJECUTAR - 01 INGESTA (Drive real) no
// entrego drive_file_id para algun cierre ENCONTRADO (o fallo tecnicamente y t.data.cierres nunca llego),
// v3.dev_api.procesar_lote() rechaza el lote ENTERO (IngestaDriveRequeridaError, estado_lote=ERROR) en vez de caer al
// listado local (os.listdir).
// HOTFIX 2026-09-19: el cierre y MACROS ya NO vienen de copias estaticas locales: se descargaron de Drive en ESTA corrida
// a procesar_entrada/<lote_id>/ (cierres por drive_file_id exacto; MACROS oficial vigente por nombre exacto en su carpeta).
// Plantilla y markers siguen viniendo de sus copias de origen (sin cambios).
// v3.precheck_maestro (Python) sigue decidiendo MAESTRO_APTO/BLOQUEADO (cobertura por fecha de cierre Y de depositos)
// antes de invocar el motor; este nodo no reinterpreta esa decision.
// FIX (bug real, primer intento oficial 10/09): el INTERPRETAR del subworkflow 01 INGESTA envuelve su salida bajo .data
// -> se lee t.data.cierres.
const payload = { lote_id: $('INTERPRETAR resultado crear_lote_pendiente').first().json.data.lote_id, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir', origen_cierres_dir: rp.dir_cierres, ruta_maestro_origen: rp.dir_entrada + '/' + rp.macros_nombre, ruta_plantilla_origen: '' + ($env.TIQ_PLANTILLA_SAP_MAESTRA || "/app/assets/Plantilla SAP maestra.xlsx") + '', markers_origen_dir: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/markers_origen', ingesta_precomputada: (t && t.data && t.data.cierres) || null, requiere_ingesta_drive: true };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_procesar_lote_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_procesar_lote_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (estado) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.query.lote_id, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_estado_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_estado_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (datos) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.query.lote_id, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_datos_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_datos_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (revisar) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.body.lote_id, fecha: t.body.fecha, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_revisar_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_revisar_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (corregir) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.body.lote_id, fecha: t.body.fecha, correccion: t.body.correccion, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_corregir_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_corregir_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
// SHADOW (migracion Railway): modo_oficial se deriva del mismo guard que
// publication_mode -- inactivo por defecto (mismo modo_oficial=true de siempre).
const guardActivo = ['true', '1', 'yes'].includes(String($env.TIQ_BLOCK_OFFICIAL_PUBLISH || '').trim().toLowerCase());
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (publicar) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
// HOTFIX 2026-09-19: modo_oficial=true -- el paso local solo PREPARA los archivos que 06B sube a Drive (un marcador local
// residual no corta el flujo ni cuenta como publicacion). El estado PUBLICADO solo lo fija la consolidacion posterior,
// con la confirmacion real de 06B/Drive.
const payload = { lote_id: t.body.lote_id, fechas: t.body.fechas, usuario_auditor: t.body.usuario_auditor || null, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir', modo_oficial: !guardActivo };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_publicar_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_publicar_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const guardActivo = ['true', '1', 'yes'].includes(String($env.TIQ_BLOCK_OFFICIAL_PUBLISH || '').trim().toLowerCase());
const data = $json.data || {};
const publicados = data.publicados || [];
// SHADOW: con el guard activo, /publicar DEV nunca llega a 06B -- 0 elegibles,
// sin importar qué haya devuelto Python. Inactivo por defecto: cálculo de siempre.
const elegibles = guardActivo ? [] : publicados.filter(function(c){ return c && c.ruta_sap_publicado && c.ruta_resultado_publicado && c.ruta_marker && c.sha256; });
return [{ json: { elegibles: elegibles, hay_elegibles: elegibles.length > 0 } }];

const original = $('INTERPRETAR resultado publicar').first().json.data || {};
const drive = $input.all().map(function(it){ return it.json; });
return [{ json: Object.assign({}, original, { publicados_drive_oficial: drive }) }];

// FASE 11A.2: el backend (no el frontend) expone el modo real de
// publicacion. 'official' porque, en este despliegue, la rama /publicar
// YA invoca TIQ V3 06B PUBLICACION OFICIAL DRIVE (ver EJECUTAR - 06B...
// en la rama /publicar de este mismo workflow). Si en el futuro /publicar
// se desconecta de 06B, este valor debe cambiar a 'dev' en el mismo lugar
// -- nunca en el frontend. Se agrega SIEMPRE, incluso si Python devolvio
// un ERROR (p. ej. sin lote_id todavia), para que el frontend pueda leer
// el modo apenas carga la pagina, antes de procesar ningun cierre.
// SHADOW (migracion Railway): con TIQ_BLOCK_OFFICIAL_PUBLISH activo el backend
// nunca declara 'official', sin importar el wiring de /publicar de arriba.
// Inactiva por defecto: mismo 'official' de siempre.
const guardActivo = ['true', '1', 'yes'].includes(String($env.TIQ_BLOCK_OFFICIAL_PUBLISH || '').trim().toLowerCase());
const original = $json.data || {};
return [{ json: Object.assign({}, original, { publication_mode: guardActivo ? 'dev' : 'official' }) }];

const t = $input.first().json;
const q = t.query || {};

// Harness minimo de solo lectura (FASE 11A.2): reenvia los campos tal
// cual llegaron por query string al subworkflow de preflight -- CERO
// logica de negocio aqui. En produccion estos mismos campos vendrian del
// lote ya procesado (fecha/archivo_esperado/sha256/drive_file_id desde
// ingesta+motor; ruta_sap_publicado/ruta_resultado_publicado son solo
// los NOMBRES oficiales deterministas, no requieren que el cierre ya se
// haya publicado localmente).
return [{
  json: {
    fecha: q.fecha || null,
    archivo_esperado: q.archivo_esperado || null,
    sha256: q.sha256 || null,
    drive_file_id: q.drive_file_id || null,
    ruta_sap_publicado: q.ruta_sap_publicado || null,
    ruta_resultado_publicado: q.ruta_resultado_publicado || null,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (generar_global) -- Python es la unica autoridad.
// FASE 12C: el navegador SOLO envia anio/mes; base_dir_dev/ruta_plantilla_origen
// son rutas fijas del lado servidor (mismo criterio que /procesar). Cero
// logica contable aqui: este nodo no valida ni decide nada de negocio.
const payload = { anio: t.body.anio, mes: t.body.mes, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir', ruta_plantilla_origen: '' + ($env.TIQ_PLANTILLA_SAP_MAESTRA || "/app/assets/Plantilla SAP maestra.xlsx") + '' };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_global_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_global_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $('WEBHOOK control1').first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (ejecutar_control1) -- Python es la unica
// autoridad. Opera sobre el GLOBAL OFICIAL que este backend acaba de
// descargar de Drive a control1_entrada/<periodo>/ (nunca sobre un GLOBAL
// local). Cero logica contable aqui.
// MODO: PRELIMINAR (mes abierto) por defecto; el cierre definitivo solo viaja
// si el frontend envia modo_control1='cerrar' Y confirmacion_cierre=true (tras
// la confirmacion humana). Aqui NUNCA se infiere el cierre.
const payload = { anio: t.body.anio, mes: t.body.mes, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir', ruta_revision_json: t.body.ruta_revision_json || null, dry_run: t.body.dry_run || false, modo_control1: t.body.modo_control1 || 'preliminar', confirmacion_cierre: t.body.confirmacion_cierre === true };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_control1_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_control1_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $('WEBHOOK control3').first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (ejecutar_control3) -- Python es la unica autoridad. Opera sobre el GLOBAL OFICIAL y los
// historicos MAESTROS que este backend acaba de descargar de Drive a control3_entrada/<periodo>/ (nunca sobre archivos
// locales). Cero logica contable aqui.
// MODO: PRELIMINAR (mes abierto) por defecto; el cierre definitivo solo viaja si el frontend envia
// modo_control3='cerrar' Y confirmacion_cierre=true (tras la confirmacion humana). Aqui NUNCA se infiere el cierre.
const payload = { anio: t.body.anio, mes: t.body.mes, base_dir_dev: '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_real_readonly_dev/dev_workdir', ruta_observaciones_json: t.body.ruta_observaciones_json || null, dry_run: t.body.dry_run || false, modo_control3: t.body.modo_control3 || 'preliminar', confirmacion_cierre: t.body.confirmacion_cierre === true };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_control3_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_control3_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const modo = (($('WEBHOOK global').item.json.body) || {}).modo || 'dev';
const r = $json.data;
const guardActivo = ['true', '1', 'yes'].includes(String($env.TIQ_BLOCK_OFFICIAL_PUBLISH || '').trim().toLowerCase());
// SHADOW: con el guard activo, debe_publicar=false aunque el request diga modo='official'.
const debePublicar = !guardActivo && modo === 'official' && r.estado === 'VALIDADO_PENDIENTE_PUBLICACION';
return [{ json: { debe_publicar: debePublicar, ruta_sap: r.ruta_global_generado, ruta_resultado: r.ruta_resultado_json } }];

const d = $('DECIDIR - Publicar GLOBAL oficial').item.json;
const carpetaId = $json.carpeta_id;
return [
  { json: { carpeta_id: carpetaId, nombre_archivo: d.ruta_sap.split('/').pop(), ruta_local_origen: d.ruta_sap, modo_si_existe: 'actualizar' } },
  { json: { carpeta_id: carpetaId, nombre_archivo: d.ruta_resultado.split('/').pop(), ruta_local_origen: d.ruta_resultado, modo_si_existe: 'actualizar' } },
];

const base = $('INTERPRETAR resultado global').item.json.data;
const subidas = $input.all().map(function(i){ return i.json; }).filter(function(j){ return j && Object.keys(j).length; });
return [{ json: { data: Object.assign({}, base, { publicacion_oficial: { publicado: true, archivos: subidas } }) } }];

const t = $json;
const modo = (t.body || {}).modo || 'dev';
return [{ json: { debe_descargar: modo === 'official' } }];

const modo = (($('WEBHOOK control1').first().json.body) || {}).modo || 'dev';
const r = $json.data || {};
const guardActivo = ['true', '1', 'yes'].includes(String($env.TIQ_BLOCK_OFFICIAL_PUBLISH || '').trim().toLowerCase());
// SHADOW: con el guard activo, debe_publicar=false aunque el request diga modo='official'.
if (guardActivo || modo !== 'official') {
  return [{ json: { debe_publicar: false, hay_revision: false, hay_detalle: false, hay_historico: false, publicar_global: false, ruta_revision: null } }];
}
const rc = $('RESOLVER control1 (periodo y carpetas)').first().json;

// Revision, detalle e historico: solo cuando la logica de CONTROL 1 los escribio en ESTA corrida.
const hayRevision = r.revision_actualizada === true && typeof r.ruta_revision === 'string' && r.ruta_revision.split('/').pop() === rc.nombre_revision;
const hayDetalle = typeof r.detalle_json === 'string' && r.detalle_json.split('/').pop() === rc.nombre_detalle;
// PRELIMINAR (mes abierto): solo artefactos del periodo (revision + detalle). El historico maestro y el
// GLOBAL solo se publican tras un CIERRE DEFINITIVO explicito.
const esCierre = r.modo_control1 === 'cerrar';
const hayHistorico = esCierre && r.historico_actualizado === true;

// GLOBAL corregido: solo si CONTROL 1 realmente lo modifico como resultado autorizado
// (validacion del auditor cerrada), es el MISMO GLOBAL oficial descargado en esta corrida
// (mismo nombre/periodo, SHA original distinto del final) y no es simulacro.
const publicarGlobal = esCierre
  && r.global_modificado === true
  && r.estado_validacion === 'CERRADO_CON_VALIDACION_AUDITOR'
  && Number(r.correcciones_aplicadas) > 0
  && r.dry_run !== true
  && r.archivo_global === rc.nombre_global
  && r.periodo === (rc.mes_nombre + '_' + rc.anio)
  && typeof r.sha256_global_original === 'string' && typeof r.sha256_global_final === 'string'
  && r.sha256_global_original !== r.sha256_global_final;

return [{ json: { debe_publicar: hayRevision || hayDetalle || hayHistorico || publicarGlobal, hay_revision: hayRevision, hay_detalle: hayDetalle, hay_historico: hayHistorico, publicar_global: publicarGlobal, ruta_revision: hayRevision ? r.ruta_revision : null } }];

// Estructura en Drive: historico CANONICO en la raiz de 05_CONTROLES; artefactos del periodo en
// CONTROL_1_ASIGNACIONES/<YYYY-MM>/ (carpeta buscada-o-creada por 07E justo antes de este nodo).
// Orden deliberado: GLOBAL corregido -> revision -> detalle -> snapshot del historico (evidencia del periodo)
// -> historico MAESTRO de la raiz SIEMPRE al final: si algo falla antes, la fuente canonica nunca queda
// adelantada respecto de lo que se publico.
const d = $('DECIDIR - Publicar CONTROL1 oficial').first().json;
const rc = $('RESOLVER control1 (periodo y carpetas)').first().json;
const carpetaPeriodo = $('EJECUTAR 07E carpeta del periodo CONTROL1').first().json.carpeta_id;
if (!carpetaPeriodo) { throw new Error('CARPETA_PERIODO_CONTROL1_NO_RESUELTA: 07E no devolvio carpeta_id para ' + rc.periodo); }
const items = [];
if (d.publicar_global) {
  items.push({ carpeta_id: rc.carpeta_global_id, nombre_archivo: rc.nombre_global, ruta_local_origen: rc.dir_entrada + '/' + rc.nombre_global, modo_si_existe: 'actualizar' });
}
if (d.hay_revision) {
  items.push({ carpeta_id: carpetaPeriodo, nombre_archivo: rc.nombre_revision, ruta_local_origen: rc.dir_entrada + '/' + rc.nombre_revision, modo_si_existe: 'actualizar' });
}
if (d.hay_detalle) {
  items.push({ carpeta_id: carpetaPeriodo, nombre_archivo: rc.nombre_detalle, ruta_local_origen: rc.dir_entrada + '/' + rc.nombre_detalle, modo_si_existe: 'actualizar' });
}
if (d.hay_historico) {
  items.push({ carpeta_id: carpetaPeriodo, nombre_archivo: rc.nombre_historico, ruta_local_origen: rc.dir_entrada + '/' + rc.nombre_historico, modo_si_existe: 'actualizar' });
  items.push({ carpeta_id: rc.carpeta_controles_id, nombre_archivo: rc.nombre_historico, ruta_local_origen: rc.dir_entrada + '/' + rc.nombre_historico, modo_si_existe: 'actualizar' });
}
